class StreamingVideoWriter:
    """Incremental version of :func:`write_video_exact`.

    Opens one ffmpeg process and lets callers append uint8 frame batches
    ([T, H, W, 3]) chunk by chunk, so the full clip never has to exist in RAM.
    Uses the exact same ffmpeg arguments/quality as ``write_video_exact``.
    ``close()`` finalizes the file; ``abort()`` kills ffmpeg and removes the
    partial file (used on cancellation/error)."""

    def __init__(self, output_path, fps, width, height):
        self.output_path = output_path
        # v2: see gen_inpainting_v2_engine PATCHES (#4)
        self.part_path = output_path + ".part"   # not *.mp4: no clip list picks it up
        self.width = int(width)
        self.height = int(height)
        rate = str(fps)
        _args = _V2_VIDEO["args"]  # v2: Inpainting's Encoding Settings (set_output_encoding)
        # the settings' encoders (NVENC included) are the system ffmpeg's, as every other stage's
        ffmpeg_exe = "ffmpeg" if _args else imageio_ffmpeg.get_ffmpeg_exe()
        _muxer = "mov" if output_path.lower().endswith(".mov") else "mp4"
        cmd = [
            ffmpeg_exe, "-y", "-hide_banner", "-loglevel", "error",
            "-f", "rawvideo", "-pix_fmt", "rgb24", "-s", f"{self.width}x{self.height}",
            "-r", rate, "-i", "-",
            "-an"] + (list(_args) if _args else ["-c:v", "libx264", "-pix_fmt", "yuv420p", "-crf", "18"]) + [
            "-r", rate, "-f", _muxer, self.part_path,
        ]
        self.proc = subprocess.Popen(cmd, stdin=subprocess.PIPE, stderr=subprocess.PIPE)
        self.frames_written = 0
        self._closed = False

    def append(self, frames):
        """Append frames ([T, H, W, 3] uint8 ndarray) to the stream."""
        frames = np.ascontiguousarray(frames)
        if frames.dtype != np.uint8:
            frames = (np.clip(frames, 0.0, 1.0) * 255.0).round().astype(np.uint8)
        if frames.ndim != 4 or frames.shape[3] != 3:
            raise ValueError(f"Expected frames of shape [T, H, W, 3], got {frames.shape}")
        if frames.shape[1] != self.height or frames.shape[2] != self.width:
            raise ValueError(
                f"Frame size {frames.shape[2]}x{frames.shape[1]} does not match "
                f"writer {self.width}x{self.height}"
            )
        try:
            self.proc.stdin.write(frames.tobytes())
        except (BrokenPipeError, OSError) as e:
            stderr = self.proc.stderr.read().decode("utf-8", "ignore") if self.proc.stderr else ""
            raise RuntimeError(f"ffmpeg pipe failed writing {self.output_path}:\n{stderr}") from e
        self.frames_written += frames.shape[0]

    def close(self):
        if self._closed:
            return self.output_path
        self._closed = True
        try:
            self.proc.stdin.close()
        except (BrokenPipeError, OSError):
            pass
        stderr = self.proc.stderr.read().decode("utf-8", "ignore") if self.proc.stderr else ""
        ret = self.proc.wait()
        if ret != 0:
            self._remove_part()
            raise RuntimeError(f"ffmpeg failed ({ret}) writing {self.output_path}:\n{stderr}")
        try:
            os.replace(self.part_path, self.output_path)
        except OSError:
            self._remove_part()  # v2: not left behind when the replace is refused
            raise
        return self.output_path

    def _remove_part(self):
        try:
            if os.path.exists(self.part_path):
                os.remove(self.part_path)
        except OSError:
            pass

    def abort(self):
        """Kill ffmpeg and delete the partial output (cancellation/error path)."""
        if self._closed:
            return
        self._closed = True
        try:
            self.proc.stdin.close()
        except (BrokenPipeError, OSError):
            pass
        try:
            self.proc.kill()
            self.proc.wait(timeout=10)
        except Exception:
            pass
        self._remove_part()     # the finished output, if any, is untouched


class FlowMatchScheduler():

    def __init__(self,):
        self.set_timesteps_fn = FlowMatchScheduler.set_timesteps_wan
        self.num_train_timesteps = 1000

    @staticmethod
    def set_timesteps_wan(num_inference_steps=100, denoising_strength=1.0, shift=None):
        sigma_min = 0.0
        sigma_max = 1.0
        shift = 5 if shift is None else shift
        num_train_timesteps = 1000
        sigma_start = sigma_min + (sigma_max - sigma_min) * denoising_strength
        sigmas = torch.linspace(sigma_start, sigma_min, num_inference_steps + 1)[:-1]
        sigmas = shift * sigmas / (1 + (shift - 1) * sigmas)
        timesteps = sigmas * num_train_timesteps
        return sigmas, timesteps
        
    def set_timesteps(self, num_inference_steps=100, denoising_strength=1.0, **kwargs):
        self.sigmas, self.timesteps = self.set_timesteps_fn(
            num_inference_steps=num_inference_steps,
            denoising_strength=denoising_strength,
            **kwargs,
        )

    def step(self, model_output, timestep, sample, to_final=False, **kwargs):
        if isinstance(timestep, torch.Tensor):
            timestep = timestep.cpu()
        timestep_id = torch.argmin((self.timesteps - timestep).abs())
        sigma = self.sigmas[timestep_id]
        if to_final or timestep_id + 1 >= len(self.timesteps):
            sigma_ = 0
        else:
            sigma_ = self.sigmas[timestep_id + 1]
        prev_sample = sample + model_output * (sigma_ - sigma)
        return prev_sample
    

def encode_vae_mode(vae, x):
    dist = vae.encode(x).latent_dist
    return dist.mode() if hasattr(dist, "mode") else dist.mean

def basic_clean(text):
    text = ftfy.fix_text(text)
    text = html.unescape(html.unescape(text))
    return text.strip()

def whitespace_clean(text):
    text = re.sub(r"\s+", " ", text)
    text = text.strip()
    return text

def prompt_clean(text):
    text = whitespace_clean(basic_clean(text))
    return text


def get_t5_prompt_embeds(
    prompt = None,
    num_videos_per_prompt = 1,
    max_sequence_length = 226,
    device = None,
    dtype = None,
    tokenizer = None,
    text_encoder = None,
):
    # device = device or self._execution_device
    # dtype = dtype or self.text_encoder.dtype

    prompt = [prompt] if isinstance(prompt, str) else prompt
    prompt = [prompt_clean(u) for u in prompt]
    batch_size = len(prompt)

    text_inputs = tokenizer(
        prompt,
        padding="max_length",
        max_length=max_sequence_length,
        truncation=True,
        add_special_tokens=True,
        return_attention_mask=True,
        return_tensors="pt",
    )
    text_input_ids, mask = text_inputs.input_ids, text_inputs.attention_mask
    seq_lens = mask.gt(0).sum(dim=1).long()

    prompt_embeds = text_encoder(text_input_ids.to(device), mask.to(device)).last_hidden_state
    prompt_embeds = prompt_embeds.to(dtype=dtype, device=device)
    prompt_embeds = [u[:v] for u, v in zip(prompt_embeds, seq_lens)]
    prompt_embeds = torch.stack(
        [torch.cat([u, u.new_zeros(max_sequence_length - u.size(0), u.size(1))]) for u in prompt_embeds], dim=0
    )

    # duplicate text embeddings for each generation per prompt, using mps friendly method
    _, seq_len, _ = prompt_embeds.shape
    prompt_embeds = prompt_embeds.repeat(1, num_videos_per_prompt, 1)
    prompt_embeds = prompt_embeds.view(batch_size * num_videos_per_prompt, seq_len, -1)

    return prompt_embeds


def encode_prompt(
    prompt,
    negative_prompt = None,
    do_classifier_free_guidance = True,
    num_videos_per_prompt = 1,
    prompt_embeds = None,
    negative_prompt_embeds = None,
    max_sequence_length = 226,
    device = None,
    dtype = None,
    tokenizer = None,
    text_encoder = None,
):
    r"""
    Encodes the prompt into text encoder hidden states.

    Args:
        prompt (`str` or `List[str]`, *optional*):
            prompt to be encoded
        negative_prompt (`str` or `List[str]`, *optional*):
            The prompt or prompts not to guide the image generation. If not defined, one has to pass
            `negative_prompt_embeds` instead. Ignored when not using guidance (i.e., ignored if `guidance_scale` is
            less than `1`).
        do_classifier_free_guidance (`bool`, *optional*, defaults to `True`):
            Whether to use classifier free guidance or not.
        num_videos_per_prompt (`int`, *optional*, defaults to 1):
            Number of videos that should be generated per prompt. torch device to place the resulting embeddings on
        prompt_embeds (`torch.Tensor`, *optional*):
            Pre-generated text embeddings. Can be used to easily tweak text inputs, *e.g.* prompt weighting. If not
            provided, text embeddings will be generated from `prompt` input argument.
        negative_prompt_embeds (`torch.Tensor`, *optional*):
            Pre-generated negative text embeddings. Can be used to easily tweak text inputs, *e.g.* prompt
            weighting. If not provided, negative_prompt_embeds will be generated from `negative_prompt` input
            argument.
        device: (`torch.device`, *optional*):
            torch device
        dtype: (`torch.dtype`, *optional*):
            torch dtype
    """
    # device = device or self._execution_device

    prompt = [prompt] if isinstance(prompt, str) else prompt
    if prompt is not None:
        batch_size = len(prompt)
    else:
        batch_size = prompt_embeds.shape[0]

    if prompt_embeds is None:
        prompt_embeds = get_t5_prompt_embeds(
            prompt=prompt,
            num_videos_per_prompt=num_videos_per_prompt,
            max_sequence_length=max_sequence_length,
            device=device,
            dtype=dtype,
            tokenizer=tokenizer,
            text_encoder=text_encoder,
        )

    if do_classifier_free_guidance and negative_prompt_embeds is None:
        negative_prompt = negative_prompt or ""
        negative_prompt = batch_size * [negative_prompt] if isinstance(negative_prompt, str) else negative_prompt

        if prompt is not None and type(prompt) is not type(negative_prompt):
            raise TypeError(
                f"`negative_prompt` should be the same type to `prompt`, but got {type(negative_prompt)} !="
                f" {type(prompt)}."
            )
        elif batch_size != len(negative_prompt):
            raise ValueError(
                f"`negative_prompt`: {negative_prompt} has batch size {len(negative_prompt)}, but `prompt`:"
                f" {prompt} has batch size {batch_size}. Please make sure that passed `negative_prompt` matches"
                " the batch size of `prompt`."
            )

        negative_prompt_embeds = get_t5_prompt_embeds(
            prompt=negative_prompt,
            num_videos_per_prompt=num_videos_per_prompt,
            max_sequence_length=max_sequence_length,
            device=device,
            dtype=dtype,
            tokenizer=tokenizer,
            text_encoder=text_encoder,
        )

    return prompt_embeds, negative_prompt_embeds


def prepare_masks(
    mask: torch.Tensor,
    reference_images = None,
    # generator = None,
    transformer_patch_size = None,
    vae_scale_factor_temporal = None,
    vae_scale_factor_spatial = None,
) -> torch.Tensor:
    # if isinstance(generator, list):
    #     # TODO: support this
    #     raise ValueError("Passing a list of generators is not yet supported. This may be supported in the future.")

    if reference_images is None:
        # For each batch of video, we set no reference image (as one or more can be passed by user)
        reference_images = [[None] for _ in range(mask.shape[0])]
    else:
        if mask.shape[0] != len(reference_images):
            raise ValueError(
                f"Batch size of `mask` {mask.shape[0]} and length of `reference_images` {len(reference_images)} does not match."
            )

    # if mask.shape[0] != 1:
    #     # TODO: support this
    #     raise ValueError(
    #         "Generating with more than one video is not yet supported. This may be supported in the future."
    #     )

    # transformer_patch_size = (
    #     self.transformer.config.patch_size[1]
    #     if self.transformer is not None
    #     else self.transformer_2.config.patch_size[1]
    # )

    mask_list = []
    for mask_, reference_images_batch in zip(mask, reference_images):
        num_channels, num_frames, height, width = mask_.shape
        new_num_frames = (num_frames + vae_scale_factor_temporal - 1) // vae_scale_factor_temporal
        new_height = height // (vae_scale_factor_spatial * transformer_patch_size) * transformer_patch_size
        new_width = width // (vae_scale_factor_spatial * transformer_patch_size) * transformer_patch_size
        mask_ = mask_[0, :, :, :]
        mask_ = mask_.view(
            num_frames, new_height, vae_scale_factor_spatial, new_width, vae_scale_factor_spatial
        )
        mask_ = mask_.permute(2, 4, 0, 1, 3).flatten(0, 1)  # [8x8, num_frames, new_height, new_width]
        mask_ = torch.nn.functional.interpolate(
            mask_.unsqueeze(0), size=(new_num_frames, new_height, new_width), mode="nearest-exact"
        ).squeeze(0)
        num_ref_images = len(reference_images_batch)
        if num_ref_images > 0:
            mask_padding = torch.zeros_like(mask_[:, :num_ref_images, :, :])
            mask_ = torch.cat([mask_padding, mask_], dim=1)
        mask_list.append(mask_)
    return torch.stack(mask_list)


def preprocess_conditions(
    video = None,
    mask = None,
    reference_images = None,
    batch_size: int = 1,
    height: int = 480,
    width: int = 832,
    num_frames: int = 81,
    dtype = None,
    device = None,
    video_processor = None,
    base = None,
):
    if video is not None:
        # base = self.vae_scale_factor_spatial * (
        #     self.transformer.config.patch_size[1]
        #     if self.transformer is not None
        #     else self.transformer_2.config.patch_size[1]
        # )
        video_height, video_width = video_processor.get_default_height_width(video[0])

        if video_height * video_width > height * width:
            scale = min(width / video_width, height / video_height)
            video_height, video_width = int(video_height * scale), int(video_width * scale)

        if video_height % base != 0 or video_width % base != 0:
            # logger.warning(
            #     f"Video height and width should be divisible by {base}, but got {video_height} and {video_width}. "
            # )
            video_height = (video_height // base) * base
            video_width = (video_width // base) * base

        assert video_height * video_width <= height * width

        video = video_processor.preprocess_video(video, video_height, video_width)
        image_size = (video_height, video_width)  # Use the height/width of video (with possible rescaling)
    else:
        video = torch.zeros(batch_size, 3, num_frames, height, width, dtype=dtype, device=device)
        image_size = (height, width)  # Use the height/width provider by user


    if mask is not None:
        mask = video_processor.preprocess_video(mask, image_size[0], image_size[1])
        mask = torch.clamp((mask + 1) / 2, min=0, max=1)
    else:
        mask = torch.ones_like(video)

    video = video.to(dtype=dtype, device=device)
    mask = mask.to(dtype=dtype, device=device)

    # Make a list of list of images where the outer list corresponds to video batch size and the inner list
    # corresponds to list of conditioning images per video
    if reference_images is None or isinstance(reference_images, Image.Image):
        reference_images = [[reference_images] for _ in range(video.shape[0])]
    elif isinstance(reference_images, (list, tuple)) and isinstance(next(iter(reference_images)), Image.Image):
        reference_images = [reference_images]
    elif (
        isinstance(reference_images, (list, tuple))
        and isinstance(next(iter(reference_images)), list)
        and isinstance(next(iter(reference_images[0])), Image.Image)
    ):
        reference_images = reference_images
    else:
        raise ValueError(
            "`reference_images` has to be of type `PIL.Image.Image` or `list` of `PIL.Image.Image`, or "
            "`list` of `list` of `PIL.Image.Image`, but is {type(reference_images)}"
        )

    if video.shape[0] != len(reference_images):
        raise ValueError(
            f"Batch size of `video` {video.shape[0]} and length of `reference_images` {len(reference_images)} does not match."
        )

    ref_images_lengths = [len(reference_images_batch) for reference_images_batch in reference_images]
    if any(l != ref_images_lengths[0] for l in ref_images_lengths):
        raise ValueError(
            f"All batches of `reference_images` should have the same length, but got {ref_images_lengths}. Support for this "
            "may be added in the future."
        )

    reference_images_preprocessed = []
    for i, reference_images_batch in enumerate(reference_images):
        preprocessed_images = []
        for j, image in enumerate(reference_images_batch):
            if image is None:
                continue
            image = video_processor.preprocess(image, None, None)
            img_height, img_width = image.shape[-2:]
            scale = min(image_size[0] / img_height, image_size[1] / img_width)
            new_height, new_width = int(img_height * scale), int(img_width * scale)
            resized_image = torch.nn.functional.interpolate(
                image, size=(new_height, new_width), mode="bilinear", align_corners=False
            ).squeeze(0)  # [C, H, W]
            top = (image_size[0] - new_height) // 2
            left = (image_size[1] - new_width) // 2
            canvas = torch.ones(3, *image_size, device=device, dtype=dtype)
            canvas[:, top : top + new_height, left : left + new_width] = resized_image
            preprocessed_images.append(canvas)
        reference_images_preprocessed.append(preprocessed_images)

    return video, mask, reference_images_preprocessed


def prepare_video_latents(
    video: torch.Tensor,
    mask: torch.Tensor,
    reference_images = None,
    device = None,
    vae = None,
) -> torch.Tensor:
    # device = device or self._execution_device

    # if isinstance(generator, list):
    #     # TODO: support this
    #     raise ValueError("Passing a list of generators is not yet supported. This may be supported in the future.")

    if reference_images is None:
        # For each batch of video, we set no re
        # ference image (as one or more can be passed by user)
        reference_images = [[None] for _ in range(video.shape[0])]
    else:
        if video.shape[0] != len(reference_images):
            raise ValueError(
                f"Batch size of `video` {video.shape[0]} and length of `reference_images` {len(reference_images)} does not match."
            )

    # if video.shape[0] != 1:
    #     # TODO: support this
    #     raise ValueError(
    #         "Generating with more than one video is not yet supported. This may be supported in the future."
    #     )

    vae_dtype = vae.dtype
    video = video.to(dtype=vae_dtype)

    latents_mean = torch.tensor(vae.config.latents_mean, device=device, dtype=torch.float32).view(
        1, vae.config.z_dim, 1, 1, 1
    )
    latents_std = 1.0 / torch.tensor(vae.config.latents_std, device=device, dtype=torch.float32).view(
        1, vae.config.z_dim, 1, 1, 1
    )

    if mask is None:
        # latents = retrieve_latents(vae.encode(video), generator, sample_mode="argmax").unbind(0)
        latents = encode_vae_mode(vae, video)
        latents = ((latents.float() - latents_mean) * latents_std).to(vae_dtype)
    else:
        mask = torch.where(mask > 0.5, 1.0, 0.0).to(dtype=vae_dtype)
        inactive = video * (1 - mask)
        reactive = video * mask
        # inactive = retrieve_latents(vae.encode(inactive), generator, sample_mode="argmax")
        inactive = encode_vae_mode(vae, inactive)
        # reactive = retrieve_latents(vae.encode(reactive), generator, sample_mode="argmax")
        reactive = encode_vae_mode(vae, reactive)
        inactive = ((inactive.float() - latents_mean) * latents_std).to(vae_dtype)
        reactive = ((reactive.float() - latents_mean) * latents_std).to(vae_dtype)
        latents = torch.cat([inactive, reactive], dim=1)


    latent_list = []
    for latent, reference_images_batch in zip(latents, reference_images):
        for reference_image in reference_images_batch:
            assert reference_image.ndim == 3
            reference_image = reference_image.to(dtype=vae_dtype)
            reference_image = reference_image[None, :, None, :, :]  # [1, C, 1, H, W]
            # reference_latent = retrieve_latents(vae.encode(reference_image), generator, sample_mode="argmax")
            reference_latent = vae.encode(reference_image).latent_dist.sample()
            reference_latent = ((reference_latent.float() - latents_mean) * latents_std).to(vae_dtype)
            reference_latent = reference_latent.squeeze(0)  # [C, 1, H, W]
            reference_latent = torch.cat([reference_latent, torch.zeros_like(reference_latent)], dim=0)
            latent = torch.cat([reference_latent.squeeze(0), latent], dim=1)
        latent_list.append(latent)

    return torch.stack(latent_list)


def blend_h(a: torch.Tensor, b: torch.Tensor, overlap_size: int) -> torch.Tensor:
    """水平方向融合 Latents，支持 [B, C, F, H, W]"""
    weight_b = (torch.arange(overlap_size).view(1, 1, 1, 1, -1) / overlap_size).to(b.device, dtype=b.dtype)
    b[:, :, :, :, :overlap_size] = (1 - weight_b) * a[:, :, :, :, -overlap_size:] + weight_b * b[:, :, :, :, :overlap_size]
    return b


def blend_v(a: torch.Tensor, b: torch.Tensor, overlap_size: int) -> torch.Tensor:
    """垂直方向融合 Latents，支持 [B, C, F, H, W]"""
    weight_b = (torch.arange(overlap_size).view(1, 1, 1, -1, 1) / overlap_size).to(b.device, dtype=b.dtype)
    b[:, :, :, :overlap_size, :] = (1 - weight_b) * a[:, :, :, -overlap_size:, :] + weight_b * b[:, :, :, :overlap_size, :]
    return b


#: v2: each denoise step, to Studio's numbers (studio/job_stats.InpaintingV2Chunks): fn(n, total)
STEP_HOOK = None


def run_wan_pipeline(
    cond_frames, 
    mask_frames, 
    prompt_embeds, 
    transformer, 
    vae, 
    noise_scheduler, 
    videoprocessor,
    vae_scale_factor_spatial,
    vae_scale_factor_temporal,
    transformer_patch_size,
    should_stop=None,
):
    """封装单次 Wan 去噪 Pipeline 以供分块调用"""
    should_stop = should_stop or _never_stop
    # 此时进入的 cond_frames 是正确的 [B, C, F, H, W]
    height, width = cond_frames.shape[3], cond_frames.shape[4]
    num_frames = cond_frames.shape[2]

    with torch.no_grad():
        # VideoProcessor 强制要求输入格式为 [B, F, C, H, W]
        # 所以我们在这里做一次临时的维度翻转：[B, C, F, H, W] -> [B, F, C, H, W]
        cond_frames_vp = cond_frames.permute(0, 2, 1, 3, 4)
        mask_frames_vp = mask_frames.permute(0, 2, 1, 3, 4)
        
        condition_video, mask, reference_images = preprocess_conditions(
            video=cond_frames_vp,
            mask=mask_frames_vp,
            reference_images=None,
            batch_size=1,
            height=height,
            width=width,
            num_frames=num_frames,
            dtype=DTYPE,
            device=DEVICE,
            video_processor=videoprocessor,
            base=vae_scale_factor_spatial * transformer_patch_size,
        )
    
        conditioning_latents = prepare_video_latents(condition_video, mask, reference_images, DEVICE, vae)
        mask_for_transformer = prepare_masks(mask, reference_images, transformer_patch_size, vae_scale_factor_temporal, vae_scale_factor_spatial).to(DEVICE, dtype=DTYPE)
        control_hidden_states = torch.cat([conditioning_latents, mask_for_transformer], dim=1).to(DTYPE)

    c = transformer.config.in_channels
    f = (num_frames - 1) // vae_scale_factor_temporal + 1
    h = height // vae_scale_factor_spatial
    w = width // vae_scale_factor_spatial
    
    latents = torch.randn(1, c, f, h, w, device=DEVICE, dtype=DTYPE)

    for i, t in enumerate(noise_scheduler.timesteps):
        if should_stop():
            raise InferenceCancelled()
        timestep_tensor = t.unsqueeze(0).to(DEVICE, dtype=DTYPE)
        with torch.no_grad():
            model_pred = transformer(
                hidden_states=latents,
                timestep=timestep_tensor,
                encoder_hidden_states=prompt_embeds,
                control_hidden_states=control_hidden_states,
                return_dict=False,
            )[0]
        latents = noise_scheduler.step(model_pred, t, latents)
        if STEP_HOOK is not None:  # v2: the step to Studio's numbers
            STEP_HOOK(i + 1, len(noise_scheduler.timesteps))
    
    return latents


def spatial_tiled_process(
    cond_frames, mask_frames, tile_num, tile_overlap, prompt_embeds, transformer, vae, noise_scheduler, videoprocessor,
    vae_scale_factor_spatial, vae_scale_factor_temporal, transformer_patch_size, should_stop=None
):
    """处理单段视频的空间分块"""
    should_stop = should_stop or _never_stop
    if tile_num == 1:
        return run_wan_pipeline(cond_frames, mask_frames, prompt_embeds, transformer, vae, noise_scheduler, videoprocessor, vae_scale_factor_spatial, vae_scale_factor_temporal, transformer_patch_size, should_stop=should_stop)

    height = cond_frames.shape[3]
    width = cond_frames.shape[4]
    
    # 确保切块大小能够被 VAE 和 Transformer Patch 的乘积（通常是 16）整除
    base = vae_scale_factor_spatial * transformer_patch_size
    tile_size = (
        int((height + tile_overlap * (tile_num - 1)) / tile_num) // base * base,
        int((width + tile_overlap * (tile_num - 1)) / tile_num) // base * base
    )
    tile_stride = (tile_size[0] - tile_overlap, tile_size[1] - tile_overlap)

    cols = []
    for i in range(tile_num):
        rows = []
        for j in range(tile_num):
            h_start = min(i * tile_stride[0], height - tile_size[0])
            w_start = min(j * tile_stride[1], width - tile_size[1])
            
            cond_tile = cond_frames[:, :, :, h_start : h_start + tile_size[0], w_start : w_start + tile_size[1]]
            mask_tile = mask_frames[:, :, :, h_start : h_start + tile_size[0], w_start : w_start + tile_size[1]]

            tile_latent = run_wan_pipeline(
                cond_tile, mask_tile, prompt_embeds, transformer, vae, noise_scheduler, videoprocessor,
                vae_scale_factor_spatial, vae_scale_factor_temporal, transformer_patch_size, should_stop=should_stop
            )
            rows.append(tile_latent)
        cols.append(rows)

    # 映射回 Latent 空间的 stride 和 overlap
    latent_stride = (tile_stride[0] // vae_scale_factor_spatial, tile_stride[1] // vae_scale_factor_spatial)
    latent_overlap = (tile_overlap // vae_scale_factor_spatial, tile_overlap // vae_scale_factor_spatial)

    # 融合 Latents
    results_cols = []
    for i, rows in enumerate(cols):
        results_rows = []
        for j, tile in enumerate(rows):
            if i > 0:
                tile = blend_v(cols[i - 1][j], tile, latent_overlap[0])
            if j > 0:
                tile = blend_h(rows[j - 1], tile, latent_overlap[1])
            results_rows.append(tile)
        results_cols.append(results_rows)

    pixels = []
    for i, rows in enumerate(results_cols):
        for j, tile in enumerate(rows):
            if i < len(results_cols) - 1:
                tile = tile[:, :, :, :latent_stride[0], :]
            if j < len(rows) - 1:
                tile = tile[:, :, :, :, :latent_stride[1]]
            rows[j] = tile
        pixels.append(torch.cat(rows, dim=4))
    
    return torch.cat(pixels, dim=3)


def plan_next_chunk(global_len, total_frames, frames_chunk, frames_overlap, vae_scale_factor_temporal):
    """Decide the next temporal chunk's start and (valid) length.

    Returns ``(start, length)`` where ``length`` is always a valid VAE temporal size
    (``length % vsft == 1``). For the final chunk the start is chosen so the chunk
    lands exactly on the last frame while keeping the overlap at or just below
    ``frames_overlap`` -- instead of the old behaviour that forced a full
    ``frames_chunk`` window and produced a huge overlap on the tail.
    """
    vsft = vae_scale_factor_temporal

    def round_down(n):
        return ((n - 1) // vsft) * vsft + 1

    if global_len == 0:
        return 0, round_down(min(frames_chunk, total_frames))

    desired_start = global_len - frames_overlap
    remaining = total_frames - desired_start  # frames from the desired start to the end

    if remaining > frames_chunk:
        # Middle chunk: step forward by exactly the requested overlap.
        return desired_start, round_down(frames_chunk)

    # Final chunk: anchor the end on the last frame so the output length matches the
    # input length. Pick the largest valid length that fits the clip (and frames_chunk)
    # and keeps overlap <= frames_overlap; rounding the length DOWN only ever shrinks
    # the overlap, never grows it.
    uncovered = total_frames - global_len
    max_len = min(frames_chunk, total_frames)
    length = round_down(min(uncovered + frames_overlap, max_len))
    start = max(0, total_frames - length)
    start = min(start, global_len)             # never produce a negative overlap
    length = round_down(total_frames - start)  # exact valid length for [start, total_frames]

    # A small frames_overlap (0 or 1, both accepted by validation) rounds this
    # down to a single frame, and then does it again and again: each pass is a
    # full diffusion run producing one output frame. Grow the chunk backwards
    # instead. The extra frames are re-rendered, not appended -- the caller
    # keeps only the frames past actual_overlap -- so the output length is
    # unchanged and only the wasted passes go away.
    smallest_useful = round_down(vsft + 1)
    if length < smallest_useful:
        wanted = min(smallest_useful, round_down(max_len))
        candidate_start = max(0, total_frames - wanted)
        if candidate_start <= global_len:
            start = candidate_start
            length = round_down(total_frames - start)

    return start, length


class WanInpaintEngine:
    """Holds the loaded Wan VACE models and derived constants so they can be
    reused across multiple videos (load once, run many)."""

    def __init__(self, tokenizer, text_encoder, vae, transformer, device, dtype, offload_mode="none",
                 offloadobj=None):
        self.tokenizer = tokenizer
        self.text_encoder = text_encoder
        self.vae = vae
        self.transformer = transformer
        self.device = device
        self.dtype = dtype
        self.offload_mode = offload_mode
        self.offloadobj = offloadobj  # mmgp offload handle (release() before dropping the engine)

        self.videoprocessor = VideoProcessor(vae_scale_factor=vae.config.scale_factor_spatial)
        self.transformer_patch_size = transformer.config.patch_size[1]
        self.vae_scale_factor_temporal = 2 ** sum(vae.temperal_downsample)
        self.vae_scale_factor_spatial = 2 ** len(vae.temperal_downsample)
        self._prompt_cache = {}

    def get_prompt_embeds(self, prompt):
        """Encodes ``prompt`` (with caching). Cached embeds survive the text
        encoder being released, so batch runs with a constant prompt keep working."""
        key = str(prompt)
        cached = self._prompt_cache.get(key)
        if cached is not None:
            return cached.to(device=self.device, dtype=self.dtype)
        if self.text_encoder is None:
            raise RuntimeError(
                "Text encoder was released to save RAM and this prompt is not cached. "
                "Reload the models (or disable 'free text encoder') to use a new prompt."
            )
        with torch.no_grad():
            prompt_embeds, _ = encode_prompt(
                [key], do_classifier_free_guidance=False, max_sequence_length=226,
                device=self.device, dtype=self.dtype,
                tokenizer=self.tokenizer, text_encoder=self.text_encoder,
            )
        self._prompt_cache[key] = prompt_embeds.detach().to("cpu")
        return prompt_embeds

    def release_text_encoder(self):
        """Frees the UMT5 text encoder (~11 GB in bf16). Cached prompt embeds keep
        working; encoding a NEW prompt afterwards requires reloading the models."""
        if self.text_encoder is None:
            return
        if self.offloadobj is not None:
            # mmgp holds its own references to every model it manages (and the
            # pinned host copies), so dropping ours frees nothing -- it would
            # only log a saving that never happens. Its memory goes back in
            # release(), when the whole engine does.
            logger.info("Text encoder is managed by mmgp; not releasing it separately.")
            return
        logger.info("Releasing text encoder to reclaim ~11 GB of %s memory.",
                    "CPU RAM" if self.offload_mode.startswith("group") or self.offload_mode == "fp8"
                    else "VRAM")
        self.text_encoder = None
        gc.collect()
        release_cuda_memory()

    def release(self):
        """Release external offload resources (mmgp pinned buffers/hooks), if any."""
        if self.offloadobj is not None:
            try:
                self.offloadobj.release()
            except Exception as e:
                logger.warning("mmgp offload release failed: %s", e)
            self.offloadobj = None


def _load_fp8_transformer(fp8_dir):
    """Load a pre-quantized FP8 transformer exported by export_fp8_transformer.py.

    Meta-device init + ``assign`` load keeps peak RAM at ~the checkpoint size
    (~16 GiB) instead of materializing the ~28 GiB bf16 model first."""
    import torchao  # noqa: F401  - required to unpickle Float8Tensor weights
    from accelerate import init_empty_weights

    cfg = WanVACETransformer3DModel.load_config(fp8_dir)
    with init_empty_weights():
        tf = WanVACETransformer3DModel.from_config(cfg)
    # weights_only=False: the file contains torchao tensor subclasses and is a
    # locally generated, trusted artifact (see export_fp8_transformer.py).
    sd = torch.load(os.path.join(fp8_dir, FP8_STATE_FILE), map_location="cpu", weights_only=False)
    tf.load_state_dict(sd, assign=True)
    return tf


def _setup_compile():
    """torch.compile's settings, as V1's (pipelines/stereo_video_inpainting.py): the kernels
    kept beside the repo so the warm-up is paid once per size, a raised recompile limit
    (chunk / tile sizes vary), and suppress_errors -- a broken toolchain runs uncompiled."""
    import torch._dynamo as dynamo
    from core.common.msvc_env import load_msvc_env
    load_msvc_env()  # cl.exe for Inductor's C++ parts (user, 2026-10-12: they fell back without it)
    os.environ.setdefault("TORCHINDUCTOR_CACHE_DIR", str(_REPO / "torchinductor_cache"))
    for knob in ("recompile_limit", "cache_size_limit"):
        if hasattr(dynamo.config, knob):
            setattr(dynamo.config, knob, 64)
    dynamo.config.suppress_errors = True


def load_models(pre_trained_path, transformer_path, device=DEVICE, dtype=DTYPE,
                offload_mode="none", use_sageattention=False, disk_offload_dir=None,
                use_compile=False,  # v2: Torch Compile (user, 2026-10-11)
                progress_cb=None):
    """Loads the tokenizer, text encoder, VAE and transformer once and returns a
    :class:`WanInpaintEngine`. Heavy and slow; call once and reuse the engine.

    ``offload_mode``:
      * ``"none"``        -> all models resident on ``device`` (fastest; needs the VRAM).
      * ``"transformer"`` -> only the 14B transformer is block-level CPU-offloaded;
        the text encoder + VAE stay resident on the GPU. Saves ~12 GB of system RAM
        vs ``"group"`` at the cost of ~12 GB more VRAM (needs a ~24 GB+ card).
      * ``"group"``       -> everything CPU-offloaded. The models stay on CPU and
        their weights are streamed to the GPU on demand, letting the 14B
        transformer run on far less VRAM (slower due to PCIe transfers; needs
        enough system RAM/pagefile to hold all weights).
      * ``"group_disk"``  -> like ``"group"`` but the transformer blocks live on DISK
        (``disk_offload_dir``) instead of CPU RAM. Slashes system RAM use for weights,
        at a further speed cost (heavy NVMe reads). Needs a diffusers version whose
        group offloading supports ``offload_to_disk_path``; falls back to ``"group"``.
      * ``"fp8"``         -> the transformer is loaded from the pre-quantized FP8
        checkpoint at ``<transformer_path>-FP8`` and kept fully GPU-resident
        (~16 GiB weights; needs a ~24 GB+ card). Text encoder + VAE are
        leaf-level CPU-offloaded. No PCIe streaming for the transformer ->
        fastest option on cards that fit it. Requires running
        export_fp8_transformer.py once (or copying its output folder).
      * ``"mmgp"``        -> all models managed by the mmgp library: the
        transformer is quantized to int8 (quanto) at load and streamed through
        an async pinned-RAM shuttle. ~30%% faster than ``"group"`` at ~3-4 GB
        VRAM, holding ~28-31 GB of system RAM. mmgp page-locks at most
        perc_reserved_mem_max (0.40 on Windows) of physical RAM and leaves the rest
        pageable (12.9 GB pinned on 32 GB, measured 2026-10-12), so 32 GB RAM runs
        it; the bf16 load before quantizing (~39 GB) uses the page file. One-time ~30 s quantization at
        load. Requires the ``mmgp`` package (GPLv3; installed by uv sync).
    """
    progress_cb = progress_cb or _noop_progress
    offload_mode = str(offload_mode).strip().lower()

    fp8_resident = offload_mode == "fp8"
    if fp8_resident and device.type != "cuda":
        raise RuntimeError("FP8 resident mode requires a CUDA GPU.")
    if fp8_resident:
        total_gib = torch.cuda.get_device_properties(device).total_memory / 2**30
        if total_gib < 20:
            raise RuntimeError(
                f"FP8 resident mode needs ~20 GB VRAM; this GPU has {total_gib:.0f} GB. "
                "Use 'Transformer only' or 'Group offload' instead."
            )

    mmgp_mode = offload_mode == "mmgp"
    if mmgp_mode and device.type != "cuda":
        raise RuntimeError("MMGP streaming mode requires a CUDA GPU.")
    if mmgp_mode:
        try:
            from mmgp import offload as mmgp_offload, profile_type as mmgp_profile_type
        except ImportError as e:
            raise RuntimeError(
                "MMGP streaming mode needs the 'mmgp' package. Run 'uv sync' to install it."
            ) from e

    # keep-on-CPU vs apply-diffusers-hooks are separate concerns: mmgp manages
    # its own onloading, so its models stay CPU-side but get NO diffusers hooks.
    offload_transformer = offload_mode in ("group", "group_disk", "transformer")
    offload_others = offload_mode in ("group", "group_disk", "fp8")
    keep_cpu_transformer = offload_transformer or mmgp_mode
    keep_cpu_others = offload_others or mmgp_mode
    if offload_transformer and device.type != "cuda":
        logger.warning("CPU offload requested but CUDA is unavailable; loading without offload.")
        offload_transformer = offload_others = keep_cpu_transformer = keep_cpu_others = False
        offload_mode = "none"

    def place(model, offloaded):
        # Offloaded models keep their weights on CPU; the offload hooks stream them to GPU.
        return model if offloaded else model.to(device)

    progress_cb("load_models", 0, 4, "Loading tokenizer...")
    tokenizer = AutoTokenizer.from_pretrained(pre_trained_path, subfolder="tokenizer")

    progress_cb("load_models", 1, 4, "Loading text encoder...")
    text_encoder = place(
        UMT5EncoderModel.from_pretrained(pre_trained_path, subfolder="text_encoder", torch_dtype=dtype),
        keep_cpu_others,
    )

    progress_cb("load_models", 2, 4, "Loading VAE...")
    vae = place(
        AutoencoderKLWan.from_pretrained(pre_trained_path, subfolder="vae", torch_dtype=dtype),
        keep_cpu_others,
    )

    progress_cb("load_models", 3, 4, "Loading transformer...")
    if fp8_resident:
        fp8_dir = _fp8_dir_for(transformer_path)  # v2: the models folder
        logger.info("Loading pre-quantized FP8 transformer from %s (GPU-resident).", fp8_dir)
        transformer = _load_fp8_transformer(fp8_dir).to(device)
    else:
        transformer = place(
            WanVACETransformer3DModel.from_pretrained(transformer_path, torch_dtype=dtype),
            keep_cpu_transformer,
        )

    transformer.eval()
    vae.eval()
    text_encoder.eval()

    text_encoder.requires_grad_(False)
    vae.requires_grad_(False)
    transformer.requires_grad_(False)

    if use_sageattention:
        try:
            transformer.set_attention_backend("sage")
            logger.info("SageAttention attention backend enabled for the Wan transformer.")
        except Exception as e:
            logger.warning("Could not enable SageAttention (%s); using PyTorch SDPA instead.", e)

    if use_compile:
        try:
            _setup_compile()
        except Exception as e:
            logger.warning("Could not set up torch.compile (%s); running uncompiled.", e)
            use_compile = False
    offloadobj = None
    if mmgp_mode:
        progress_cb("load_models", 4, 4, "MMGP setup (int8 quantize + pinning, ~30 s)...")
        pipe = {"transformer": transformer, "text_encoder": text_encoder, "vae": vae}
        offloadobj = mmgp_offload.profile(
            pipe, profile_no=mmgp_profile_type.HighRAM_LowVRAM,
            quantizeTransformer=True, verboseLevel=1,
            compile=["transformer"] if use_compile else False,  # v2: its own block compile
        )
        logger.info("MMGP streaming enabled: int8 transformer, async pinned shuttle.")

    offload_device = torch.device("cpu")
    if offload_transformer:
        progress_cb("load_models", 4, 4, "Enabling CPU offload...")
        logger.info(
            "Enabling block-level CPU offload for the transformer (stream overlap on)%s.",
            "" if offload_others else "; text encoder + VAE stay on GPU",
        )
        # Transformer is the large one -> block-level streaming. Stream overlap
        # requires num_blocks_per_group=1 (diffusers clamps anything else to 1).
        # low_cpu_mem_usage is essential: without it, diffusers pins ALL weights
        # (page-locked RAM) upfront at load. Pinned memory cannot be backed by
        # the page file, so on RAM-constrained systems that instantly fails with
        # a raw "CUDA error: out of memory" even though the GPU is nearly empty.
        transformer_offload_kwargs = dict(
            onload_device=device, offload_device=offload_device,
            offload_type="block_level", num_blocks_per_group=1,
            use_stream=True, low_cpu_mem_usage=True,
        )
        if offload_mode == "group_disk":
            disk_dir = disk_offload_dir or os.path.join(tempfile.gettempdir(), "wan_vace_offload_cache")
            os.makedirs(disk_dir, exist_ok=True)
            transformer_offload_kwargs["offload_to_disk_path"] = disk_dir
            logger.info("Transformer blocks will be offloaded to DISK: %s", disk_dir)
        try:
            apply_group_offloading(transformer, **transformer_offload_kwargs)
        except TypeError:
            if "offload_to_disk_path" not in transformer_offload_kwargs:
                raise
            logger.warning(
                "This diffusers version does not support offload_to_disk_path; "
                "falling back to CPU-RAM group offload."
            )
            transformer_offload_kwargs.pop("offload_to_disk_path")
            apply_group_offloading(transformer, **transformer_offload_kwargs)
    if offload_others:
        # VAE + text encoder are smaller -> leaf-level offload.
        apply_group_offloading(
            vae, onload_device=device, offload_device=offload_device,
            offload_type="leaf_level", use_stream=True, low_cpu_mem_usage=True,
        )
        apply_group_offloading(
            text_encoder, onload_device=device, offload_device=offload_device,
            offload_type="leaf_level", use_stream=True, low_cpu_mem_usage=True,
        )

    if use_compile and not mmgp_mode:
        if offload_mode in ("none", "fp8"):
            n = 0
            for name in ("blocks", "vace_blocks"):
                for block in getattr(transformer, name, None) or []:
                    block.compile(dynamic=True)
                    n += 1
            logger.info("torch.compile on for %d transformer blocks (the first chunk includes a one-time "
                        "warm-up).", n)
        else:
            logger.warning("Torch Compile skipped: it doesn't work with the %s offload's per-block hooks. "
                           "Use None, FP8 resident or MMGP streaming for it.", offload_mode)
    progress_cb("load_models", 4, 4, "Models loaded.")
    logger.info("Wan VACE models loaded (%s, offload=%s).", dtype, offload_mode)
    return WanInpaintEngine(tokenizer, text_encoder, vae, transformer, device, dtype, offload_mode,
                            offloadobj=offloadobj)


def run_inpaint(
    engine,
    input_video_path,
    save_dir,
    prompt="",
    frames_chunk=81,
    frames_overlap=10,
    tile_overlap=128,
    tile_num=2,
    inference_steps=10,
    seed=0,
    is_dual_input=None,
    free_text_encoder=True,
    progress_cb=None,
    should_stop=None,
):
    """Runs stereo inpainting on a single video and writes the outputs to ``save_dir``.

    Two input layouts are supported (matching inpainting_gui.py):

    * **Quad** (2x2 grid): top-left = left eye, bottom-left = mask,
      bottom-right = warped right. Outputs an SBS video ``[left | inpainted-right]``
      plus an anaglyph -> ``{"sbs": path, "anaglyph": path}``.
    * **Dual** (1x2 halves): left = mask, right = warped right. No left eye is
      available, so only the inpainted right eye is written -> ``{"right_eye": path}``.

    ``is_dual_input`` may be ``True``/``False`` to force a layout, or ``None`` to
    auto-detect from the filename (see :func:`detect_dual_input`).

    ``progress_cb(stage, current, total, message)`` is called for UI updates and
    ``should_stop()`` is polled between chunks and denoise steps so a caller can
    cancel; cancellation raises :class:`InferenceCancelled`.
    """
    progress_cb = progress_cb or _noop_progress
    should_stop = should_stop or _never_stop

    device = engine.device
    vae = engine.vae
    transformer = engine.transformer
    videoprocessor = engine.videoprocessor
    transformer_patch_size = engine.transformer_patch_size
    vae_scale_factor_temporal = engine.vae_scale_factor_temporal
    vae_scale_factor_spatial = engine.vae_scale_factor_spatial

    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)
        torch.manual_seed(seed)
        torch.cuda.manual_seed(seed)
        torch.cuda.manual_seed_all(seed)

    if is_dual_input is None:
        is_dual_input = detect_dual_input(input_video_path)

    os.makedirs(save_dir, exist_ok=True)
    base_name = os.path.splitext(os.path.basename(input_video_path))[0]
    video_name = base_name.replace("_splatting_results", "") + "_inpainting_results"
    logger.info("Input layout: %s", "dual (1x2)" if is_dual_input else "quad (2x2)")

    progress_cb("encode_prompt", 0, 1, "Encoding prompt...")
    logger.info("Encoding prompt...")
    prompt_embeds = engine.get_prompt_embeds(prompt)
    if free_text_encoder:
        # The UMT5 encoder (~11 GB bf16) is only needed to embed the prompt, which is
        # now cached on the engine. Drop it to reclaim RAM/VRAM for the run.
        engine.release_text_encoder()

    progress_cb("load_video", 0, 1, "Opening video...")
    logger.info("Opening video: %s", input_video_path)
    video_reader = VideoReader(input_video_path, ctx=cpu(0))
    fps = get_exact_fps(input_video_path, video_reader)
    logger.info("Source FPS: %s", fps)
    total_frames = len(video_reader)

    # STREAMING: probe dimensions from a single frame; the full clip is never
    # decoded into RAM. Each temporal chunk is decoded on demand below.
    probe = video_reader.get_batch([0]).asnumpy()  # [1, H, W, 3] uint8
    full_h, full_w = int(probe.shape[1]), int(probe.shape[2])
    del probe

    if is_dual_input:
        # Dual (1x2): left half = mask, right half = warped right eye. No left eye.
        h_orig, w_orig = full_h, full_w // 2
    else:
        # Quad (2x2): TL = left eye, BL = mask, BR = warped right eye.
        h_orig, w_orig = full_h // 2, full_w // 2

    base = vae_scale_factor_spatial * transformer_patch_size

    # Derive the tiling-perfect padded resolution (identical math to the stock
    # version; padding is purely spatial so applying it per chunk is equivalent
    # to padding the whole clip up front).
    min_tile_h = (h_orig + tile_overlap * (tile_num - 1)) / tile_num
    tile_size_h = math.ceil(min_tile_h / base) * base

    min_tile_w = (w_orig + tile_overlap * (tile_num - 1)) / tile_num
    tile_size_w = math.ceil(min_tile_w / base) * base

    tile_stride_h = tile_size_h - tile_overlap
    tile_stride_w = tile_size_w - tile_overlap

    target_h = tile_stride_h * (tile_num - 1) + tile_size_h
    target_w = tile_stride_w * (tile_num - 1) + tile_size_w

    pad_h = target_h - h_orig
    pad_w = target_w - w_orig
    if pad_h > 0 or pad_w > 0:
        logger.info(
            "Padding resolution from %dx%d to %dx%d to perfectly match Tiling output.",
            w_orig, h_orig, target_w, target_h,
        )

    noise_scheduler = FlowMatchScheduler()
    noise_scheduler.set_timesteps(num_inference_steps=inference_steps, denoising_strength=1.0)

    # v2: each finished chunk's latents kept, so a stopped or crashed clip resumes from its last
    # finished chunk (user, 2026-10-18; resume.py)
    from studio.stages.inpainting_v2.resume import ChunkCheckpoints, signature as chunk_signature
    checkpoints = ChunkCheckpoints(save_dir, video_name, chunk_signature(
        input_video_path, frames_chunk=frames_chunk, frames_overlap=frames_overlap, tile_num=tile_num,
        tile_overlap=tile_overlap, inference_steps=inference_steps, seed=seed, prompt=prompt,
        is_dual_input=is_dual_input, total_frames=total_frames,
        model={"transformer": TRANSFORMER_PATH, "offload": getattr(engine, "offload_mode", ""),
               "dtype": getattr(engine, "dtype", "")}))

    # Rolling history: only the last <= frames_chunk generated frames (at padded
    # resolution, float32, CPU) are kept for overlap conditioning. This replaces
    # the stock full-history accumulation + per-chunk torch.cat of the entire clip.
    history = None          # [1, C, K, H_pad, W_pad] float32 on CPU
    history_start = 0       # global index of history[:, :, 0]
    global_len = 0

    writers = {}
    outputs = {}
    completed = False

    def _frames_to_uint8(t):
        """[C, T, h, w] float 0-1 tensor -> [T, h, w, 3] uint8 ndarray."""
        arr = t.permute(1, 2, 3, 0).clamp_(0.0, 1.0).mul_(255.0).round_().to(torch.uint8)
        return np.ascontiguousarray(arr.numpy())

    logger.info(
        "Starting STREAMING Temporal Chunking inference (Total Frames: %d, per-eye %dx%d)...",
        total_frames, w_orig, h_orig,
    )

    try:
        while global_len < total_frames:
            if should_stop():
                raise InferenceCancelled()
            cur_i, valid_chunk_size = plan_next_chunk(
                global_len, total_frames, frames_chunk, frames_overlap, vae_scale_factor_temporal
            )

            # --- Decode ONLY this chunk (uint8), then split panels ---
            frame_indices = list(range(cur_i, cur_i + valid_chunk_size))
            chunk_u8 = torch.from_numpy(video_reader.get_batch(frame_indices).asnumpy())  # [T, H, W, 3]

            def _panel_to_float(panel_u8):
                # [T, h, w, 3] uint8 -> [1, 3, T, h, w] float32 0-1
                return panel_u8.permute(3, 0, 1, 2).unsqueeze(0).float().div_(255.0)

            left_u8 = None
            if is_dual_input:
                chunk_mask = _panel_to_float(chunk_u8[:, :, :w_orig])
                chunk_cond = _panel_to_float(chunk_u8[:, :, w_orig:])
            else:
                left_u8 = chunk_u8[:, :h_orig, :w_orig].clone()  # kept uint8 for SBS/anaglyph
                chunk_mask = _panel_to_float(chunk_u8[:, h_orig:, :w_orig])
                chunk_cond = _panel_to_float(chunk_u8[:, h_orig:, w_orig:])
            del chunk_u8

            chunk_cond = chunk_cond * (1.0 - chunk_mask) + 0.5 * chunk_mask

            # --- Per-chunk spatial padding (replicate for cond, zeros for mask) ---
            if pad_h > 0 or pad_w > 0:
                cond_4d = chunk_cond[0].permute(1, 0, 2, 3)
                cond_4d = F.pad(cond_4d, (0, pad_w, 0, pad_h), mode='replicate')
                chunk_cond = cond_4d.permute(1, 0, 2, 3).unsqueeze(0)
                del cond_4d
                chunk_mask = F.pad(chunk_mask, (0, pad_w, 0, pad_h), mode='constant', value=0)

            # --- Overlap conditioning from the rolling history buffer ---
            actual_overlap = 0
            if global_len > 0:
                actual_overlap = global_len - cur_i
                hs = cur_i - history_start
                if hs < 0 or history is None or hs + actual_overlap > history.shape[2]:
                    raise RuntimeError(
                        f"Overlap window [{cur_i}:{global_len}] outside rolling history "
                        f"(start={history_start}, len={0 if history is None else history.shape[2]})."
                    )
                chunk_cond[:, :, :actual_overlap] = history[:, :, hs : hs + actual_overlap]

            progress_cb(
                "inpaint", min(global_len, total_frames), total_frames,
                f"Processing chunk [{cur_i}:{cur_i + valid_chunk_size}] | Overlap: {actual_overlap} frames...",
            )
            logger.info(
                "Processing chunk [%d:%d] | Overlap context: %d frames...",
                cur_i, cur_i + valid_chunk_size, actual_overlap,
            )

            # --- Spatial tiled inference (unchanged) ---
            # v2: a chunk a stopped run finished: its latents, no denoise (resume.py)
            chunk_latents = checkpoints.load(cur_i, valid_chunk_size, device)
            if chunk_latents is None:
                chunk_latents = spatial_tiled_process(
                    chunk_cond, chunk_mask, tile_num, tile_overlap, prompt_embeds, transformer, vae, noise_scheduler,
                    videoprocessor, vae_scale_factor_spatial, vae_scale_factor_temporal, transformer_patch_size,
                    should_stop=should_stop,
                )
                checkpoints.save(cur_i, valid_chunk_size, chunk_latents)
            del chunk_cond, chunk_mask

            # --- Decode this chunk, move straight to CPU ---
            with torch.no_grad():
                latents_mean = torch.tensor(vae.config.latents_mean, device=device, dtype=torch.float32).view(1, vae.config.z_dim, 1, 1, 1)
                latents_std = torch.tensor(vae.config.latents_std, device=device, dtype=torch.float32).view(1, vae.config.z_dim, 1, 1, 1)
                chunk_latents = chunk_latents.float() * latents_std + latents_mean
                chunk_latents = chunk_latents.to(vae.dtype)
                video_chunk_tensor = vae.decode(chunk_latents, return_dict=False)[0]
                video_chunk_tensor = (video_chunk_tensor / 2 + 0.5).clamp(0, 1).float().cpu()
            del chunk_latents

            # --- Keep only the NEW frames; update the rolling history ---
            if global_len == 0:
                new_frames = video_chunk_tensor
            else:
                new_frames = video_chunk_tensor[:, :, actual_overlap:]
            num_new = new_frames.shape[2]
            global_len += num_new

            if history is None:
                history = new_frames
            else:
                history = torch.cat([history, new_frames], dim=2)
            if history.shape[2] > frames_chunk:
                history = history[:, :, -frames_chunk:].contiguous()
            history_start = global_len - history.shape[2]

            # --- Stream the new frames to disk (crop padding, uint8, ffmpeg) ---
            if num_new > 0:
                right_u8 = _frames_to_uint8(new_frames[0, :, :, :h_orig, :w_orig].clone())

                if is_dual_input:
                    if "right_eye" not in writers:
                        right_eye_path = os.path.join(save_dir, f"{video_name}_right_eye{_V2_VIDEO['ext']}")
                        writers["right_eye"] = StreamingVideoWriter(right_eye_path, fps, w_orig, h_orig)
                        outputs["right_eye"] = right_eye_path
                    writers["right_eye"].append(right_u8)
                else:
                    left_out_u8 = np.ascontiguousarray(left_u8[actual_overlap:].numpy())

                    if "sbs" not in writers:
                        frames_sbs_path = os.path.join(save_dir, f"{video_name}_sbs{_V2_VIDEO['ext']}")
                        writers["sbs"] = StreamingVideoWriter(frames_sbs_path, fps, w_orig * 2, h_orig)
                        outputs["sbs"] = frames_sbs_path
                        vid_anaglyph_path = os.path.join(save_dir, f"{video_name}_anaglyph{_V2_VIDEO['ext']}")
                        writers["anaglyph"] = StreamingVideoWriter(vid_anaglyph_path, fps, w_orig, h_orig)
                        outputs["anaglyph"] = vid_anaglyph_path

                    writers["sbs"].append(np.concatenate([left_out_u8, right_u8], axis=2))

                    # Anaglyph: red from the left eye, green/blue from the inpainted right.
                    anaglyph_u8 = right_u8.copy()
                    anaglyph_u8[:, :, :, 0] = left_out_u8[:, :, :, 0]
                    writers["anaglyph"].append(anaglyph_u8)
                    del left_out_u8, anaglyph_u8

                del right_u8

            del video_chunk_tensor, new_frames, left_u8

            # Stuck-progression guard (identical semantics to stock).
            if global_len > 0 and actual_overlap >= valid_chunk_size:
                logger.warning("Chunk progression stuck due to temporal scaling limits. Exiting loop.")
                break

        if global_len < total_frames:  # v2: the guard broke the loop -- not a finished clip
            raise RuntimeError(
                f"Inpainting stopped making progress after {global_len} of {total_frames} frames "
                f"(the overlap leaves no new frames per chunk); the partial output is discarded.")
        completed = True
    finally:
        if completed:
            progress_cb("export", 0, 1, "Finalizing output files...")
            first_error = None  # v2: each writer closed, the rest aborted after a failure
            for writer in writers.values():
                try:
                    if first_error is None:
                        writer.close()
                    else:
                        writer.abort()
                except Exception as e:
                    first_error = first_error or e
            if first_error is not None:
                raise first_error
        else:
            # Cancelled or errored: kill ffmpeg and remove partial outputs.
            for writer in writers.values():
                writer.abort()
        del history
        gc.collect()

    checkpoints.clear()  # v2: the clip finished: its chunk checkpoints go
    progress_cb("done", total_frames, total_frames, "Done.")
    if is_dual_input:
        logger.info("Saved:\n  Right eye: %s", outputs.get("right_eye"))
    else:
        logger.info("Saved:\n  SBS:      %s\n  Anaglyph: %s", outputs.get("sbs"), outputs.get("anaglyph"))
    return outputs


def resolve_layout(mode):
    """Map a layout mode string to ``is_dual_input`` (None = auto-detect)."""
    return {"auto": None, "dual": True, "quad": False}[str(mode).strip().lower()]


def resolve_offload(mode):
    """Map a GUI offload label to a ``load_models`` offload_mode string."""
    mode = str(mode).strip().lower()
    if mode.startswith("group"):
        return "group_disk" if "disk" in mode else "group"
    if mode.startswith("transformer"):
        return "transformer"
    if mode.startswith("fp8"):
        return "fp8"
    if mode.startswith("mmgp"):
        return "mmgp"
    return "none"


# =============================================================================
# WanInpaintRunner -- v1 WanInpaintingGUI's non-widget half
# =============================================================================


class _Var:
    """Stands in for a tk variable: reads and writes one settings key."""

    def __init__(self, runner, key):
        self._runner = runner
        self._key = key

    def get(self):
        return self._runner._values.get(self._key)

    def set(self, value):
        self._runner._values[self._key] = value
        self._runner.hooks.var(self._key, value)


class _MessageBoxShim:
    """v1's tkinter.messagebox, as prompts in the page (see the controller).
    askyesno answers with ``answer``, which the caller sets after asking in QML."""

    def __init__(self):
        self.hooks = None
        self.answer = False

    def _send(self, kind, title, message):
        if self.hooks is not None:
            self.hooks.message(kind, str(title), str(message))
        else:
            logger.warning("%s: %s", title, message)

    def showerror(self, title="", message="", **_kw):
        self._send("error", title, message)

    def showwarning(self, title="", message="", **_kw):
        self._send("warning", title, message)

    def showinfo(self, title="", message="", **_kw):
        self._send("info", title, message)

    def askyesno(self, title="", message="", **_kw):
        return bool(self.answer)


messagebox = _MessageBoxShim()


class _WakingQueue(queue.Queue):
    """v1 drained its worker queue on a 100 ms Tk timer; here each put wakes
    the controller, which calls _poll_queue on the UI thread."""

    def __init__(self, wake):
        super().__init__()
        self._wake = wake

    def put(self, item, block=True, timeout=None):
        super().put(item, block, timeout)
        self._wake()


class WanInpaintRunner:
    """One V2 stage's worth of v1 state: the settings (under v1's config key
    names), the loaded engine (kept between batches, as v1 does), the worker.

    hooks: var(key, value), message(kind, title, text), wake(), running(bool),
           claim() -> bool, release()
    """

    #: Non-settings vars v1 keeps: they only feed the progress bar / status.
    _UI_VARS = ("progress", "status")

    def __init__(self, values, hooks):
        self._values = values
        self._values.setdefault("progress", 0.0)
        self._values.setdefault("status", "Ready")
        self.hooks = hooks
        messagebox.hooks = hooks
        self.shell = None
        self.window_geometry = values.get("window_geometry")
        self.stop_event = threading.Event()
        self.worker_thread = None
        self.engine = None
        self._engine_paths = None
        self._batch_prefix = ""
        self._ui_queue = _WakingQueue(hooks.wake)
        self._job_started = None
        self.stop_after_clip = None     # Stop After Clip: a threading.Event, set by the controller
        self._batch_total, self._halted = 0, False

    def __getattr__(self, name):
        # self.<key>_var -> the settings key, as v1's tk variables were.
        if name.endswith("_var"):
            return _Var(self, name[:-4])
        raise AttributeError(name)

    # ---- the Tk surface v1's methods expect -----------------------------------

    def after(self, _delay_ms, _fn=None, *_args):
        return None          # _poll_queue re-arms itself this way; the queue wakes us instead

    def _set_running_state(self, running):
        self.hooks.running(bool(running))

    def _claim_job(self):
        return bool(self.hooks.claim())

    def _release_job(self):
        self.hooks.release()

    def _finish_verdict(self, succeeded, failed, fatal=""):
        """How the batch ended, told once (audit #3), and -- when it produced
        something -- the handoff Merging's "Import from Inpainting V2" reads."""
        v = verdict("Inpainting V2", Outcome(done=succeeded, failed=failed, error=fatal, halted=self._halted,
                                             skipped=getattr(self, "_resume_skipped", 0),
                                             note=getattr(self, "_resume_note", "")),
                    stopped=self.stop_event.is_set() and not fatal)
        if v.handoff:
            self._record_job_handoff()
        toast = getattr(self.hooks, "toast", None)
        if toast is not None:
            toast(v.kind, v.title, v.text)
        return v

    def _record_job_handoff(self):
        """Recorded beside V1's (job_handoff.SIDE_STAGES): the inpainted
        output, and the splats V2 read -- Merging's Mask Folder."""
        try:
            from core.ui.job_handoff import record_job
            src = str(self._values.get("input_folder") or "").strip()
            record_job("inpainting_v2", {
                "inpainted_out": str(self._values.get("output_folder") or "").strip(),
                "hires": os.path.dirname(src) if os.path.isfile(src) else src,
            })
        except Exception:
            logger.debug("Could not record the Inpainting V2 handoff", exc_info=True)

