    # -- v1 WanInpaintingGUI._gather_videos (inpainting_gui_v2.py:2284)
    def _gather_videos(self, input_path):
        """Resolve the input field to a sorted list of video files."""
        if os.path.isfile(input_path):
            return [input_path]
        if os.path.isdir(input_path):
            return [
                os.path.join(input_path, name)
                for name in sorted(os.listdir(input_path))
                if name.lower().endswith(VIDEO_EXTENSIONS)
            ]
        return []

    # -- v1 WanInpaintingGUI._validate_and_gather (inpainting_gui_v2.py:2296)
    def _validate_and_gather(self):
        """Validate all fields. Returns (videos, params, output_dir, prompt) or None."""
        input_path = self.input_folder_var.get().strip()
        output_dir = self.output_folder_var.get().strip()

        offload_sel = resolve_offload(self.offload_mode_var.get())
        if not os.path.isdir(PRE_TRAINED_PATH):
            messagebox.showerror("Missing models", f"Base model folder not found:\n{PRE_TRAINED_PATH}")
            return None
        # FP8 mode loads only the -FP8 folder (checked below); the bf16
        # transformer is not required for it, enabling FP8-only installs.
        if offload_sel != "fp8" and not os.path.isdir(TRANSFORMER_PATH):
            messagebox.showerror("Missing models", f"Transformer folder not found:\n{TRANSFORMER_PATH}")
            return None
        if offload_sel == "mmgp":
            try:
                import mmgp  # noqa: F401
            except ImportError:
                messagebox.showerror(
                    "mmgp not installed",
                    "MMGP streaming mode needs the 'mmgp' package.\n"
                    "Run 'uv sync' in the StereoCrafter folder (or _update.bat) and retry.",
                )
                return None
        if offload_sel == "fp8":
            fp8_dir = _fp8_dir_for(TRANSFORMER_PATH)  # v2: the models folder
            if not os.path.isfile(os.path.join(fp8_dir, FP8_STATE_FILE)):
                messagebox.showerror(
                    "FP8 checkpoint missing",
                    f"FP8 resident mode needs the pre-quantized transformer at:\n{fp8_dir}\n\n"
                    "Download it with Download FP8 Model on this page, or in Settings > Studio > Models,\n"
                    "or export it locally with export_fp8_transformer.py (needs ~64 GB RAM).",
                )
                return None
            if torch.cuda.is_available():
                total_gib = torch.cuda.get_device_properties(0).total_memory / 2**30
                if total_gib < 20:
                    messagebox.showerror(
                        "Not enough VRAM",
                        f"FP8 resident mode needs ~20 GB VRAM; this GPU has {total_gib:.0f} GB.\n"
                        "Use 'Transformer only' or 'Group offload' instead.",
                    )
                    return None
        if not input_path or not os.path.exists(input_path):
            messagebox.showerror("Invalid path", "Input folder/file does not exist.")
            return None

        videos = self._gather_videos(input_path)
        self._resume_skipped = 0  # v2: told in the finish (bug sweep A7)
        _only = getattr(self, "only_clips", None)  # v2: Upcoming Jobs' picks
        if _only:
            videos = [v for v in videos if os.path.normcase(os.path.abspath(v)) in _only]
        self._resume_dir, self._resume_note = None, ""  # v2: the resume split, on the worker
        if videos and os.path.isdir(input_path) and self.move_to_finished_var.get():
            finished_dir = os.path.join(input_path, "finished")
            if os.path.isdir(finished_dir):
                self._resume_dir = finished_dir  # v2: split on the worker (bug sweep A7)
        if not videos:
            messagebox.showerror(
                "No videos",
                "No video files found at the input path.\n"
                f"Supported extensions: {', '.join(VIDEO_EXTENSIONS)}",
            )
            return None

        if not output_dir:
            messagebox.showerror("Invalid path", "Please choose an output folder.")
            return None
        try:
            os.makedirs(output_dir, exist_ok=True)
        except OSError as e:
            messagebox.showerror("Invalid path", f"Cannot create output folder:\n{e}")
            return None

        # Numeric parameters
        specs = [
            ("frames_chunk", self.frames_chunk_var, 1),
            ("frames_overlap", self.frames_overlap_var, 0),
            ("tile_overlap", self.tile_overlap_var, 0),
            ("tile_num", self.tile_num_var, 1),
            ("inference_steps", self.inference_steps_var, 1),
            ("seed", self.seed_var, None),
        ]
        params = {}
        for name, var, minimum in specs:
            raw = var.get().strip()
            try:
                value = int(raw)
            except ValueError:
                messagebox.showerror("Invalid value", f"'{name}' must be an integer (got '{raw}').")
                return None
            if minimum is not None and value < minimum:
                messagebox.showerror("Invalid value", f"'{name}' must be >= {minimum} (got {value}).")
                return None
            params[name] = value

        if params["frames_overlap"] >= params["frames_chunk"]:
            messagebox.showerror("Invalid value", "'frames_overlap' must be smaller than 'frames_chunk'.")
            return None
        _held = ((params["frames_chunk"] - 1) // 4) * 4 + 1  # v2: what a chunk really holds (bug sweep A7)
        if params["frames_overlap"] >= _held:
            messagebox.showerror("Invalid value", f"A Frames Chunk of {params['frames_chunk']} holds {_held} frames "
                                 f"(Wan's chunks are 4n + 1), so 'frames_overlap' must be at most {_held - 1}.")
            return None

        return videos, params, output_dir

    # -- v1 WanInpaintingGUI.start_processing (inpainting_gui_v2.py:2408)
    def start_processing(self):
        if self.worker_thread is not None and self.worker_thread.is_alive():
            return
        validated = self._validate_and_gather()
        if validated is None:
            return
        videos, params, output_dir = validated
        self._batch_total, self._halted = len(videos), False  # v2: Stop After Clip
        prompt = PROMPT  # prompt input removed from the GUI; always use the default

        # Model paths are hardcoded (not exposed in the GUI).
        pre_trained = PRE_TRAINED_PATH
        transformer = TRANSFORMER_PATH

        # Input layout is always auto-detected per file (see detect_dual_input).
        is_dual_input = None
        offload_mode = resolve_offload(self.offload_mode_var.get())
        # Only batch (folder) inputs move to 'finished'; an explicitly chosen
        # single file is left in place.
        input_path = self.input_folder_var.get().strip()
        move_finished = self.move_to_finished_var.get() and os.path.isdir(input_path)
        if self.move_to_finished_var.get() and not move_finished:
            logger.info("Single-file input: processed file will be left in place (no move to 'finished').")

        # Claimed only after validation, so a rejected start can't leave the
        # shell's job claim held. This is what evicts other stages' weights
        # before a 14B load and stops them starting mid-run.
        if not self._claim_job():
            return
        # Clock starts once validation has passed and the GPU is ours, so the
        # report is Start-to-finish for the work, not time on an error dialog.
        # It includes model loading (and MMGP's quantize), which is real time
        # the user waited.
        self._job_started = time.monotonic()

        self.stop_event.clear()
        self._set_running_state(True)
        self.progress_var.set(0.0)
        logger.info("Starting batch: %d video(s) -> %s", len(videos), output_dir)

        self.worker_thread = threading.Thread(
            target=self._run_batch,
            args=(videos, params, output_dir, prompt, pre_trained, transformer,
                  is_dual_input, offload_mode, self.use_sageattention_var.get(),
                  move_finished, bool(self.free_text_encoder_var.get())),
            daemon=True,
        )
        self.worker_thread.start()

    # -- v1 WanInpaintingGUI._run_batch (inpainting_gui_v2.py:2456)
    def _run_batch(self, videos, params, output_dir, prompt, pre_trained, transformer,
                   is_dual_input, offload_mode, use_sageattention, move_finished,
                   free_text_encoder=True):
        """Worker thread: load models once, then inpaint each video.

        Must not touch Tk widgets/variables directly — all UI updates go through
        ``self._ui_queue`` (drained by ``_poll_queue`` on the main thread).
        """
        succeeded, failed = 0, 0
        fatal = ""  # v2: see gen_inpainting_v2_engine PATCHES
        try:
            _wait = getattr(self.hooks, "wait_gpu", None)  # v2: gpu_jobs.wait_for_releases (#14)
            if _wait is not None:
                _wait()
            _fin = getattr(self, "_resume_dir", None)  # v2: the resume split, off the UI thread (bug sweep A7)
            if _fin:
                _remaining, _ = split_already_finished(videos, _fin, logger)
                if len(_remaining) < len(videos):
                    self._resume_skipped = len(videos) - len(_remaining)
                    logger.info("Resume mode: skipped %d already processed video(s) found in 'finished'.",
                                len(videos) - len(_remaining))
                if not _remaining:
                    self._resume_note = ("All input videos were already processed (found in the 'finished' "
                                         "folder). Use File > Restore Finished to re-process them.")
                    return
                videos = _remaining
                self._batch_total = len(videos)
            use_compile = bool(self.use_compile_var.get())  # v2: Torch Compile (user, 2026-10-11)
            set_output_encoding(self._values.get("_encoding"))  # v2: Inpainting's Encoding Settings
            engine_key = (pre_trained, transformer, offload_mode, use_sageattention, use_compile)
            # A released text encoder can't be brought back without a reload,
            # so an engine that dropped it is only reusable while the prompt
            # is already cached (get_prompt_embeds raises otherwise).
            encoder_gone = (
                self.engine is not None and self.engine.text_encoder is None
                and str(prompt) not in self.engine._prompt_cache
            )
            if self.engine is None or self._engine_paths != engine_key or encoder_gone:
                # Drop any previous engine first so its VRAM is freed before reloading.
                if self.engine is not None:
                    self.engine.release()  # free mmgp pinned buffers/hooks, if any
                self.engine = None
                release_cuda_memory()
                gc.collect()
                self._on_progress("load_models", 0, 1, "Loading models...")
                self.engine = load_models(
                    pre_trained, transformer,
                    offload_mode=offload_mode,
                    use_sageattention=use_sageattention,
                    use_compile=use_compile,
                    disk_offload_dir=os.path.join(output_dir, "_wan_offload_cache"),
                    progress_cb=self._on_progress,
                )
                self._engine_paths = engine_key

            total = len(videos)
            for idx, video in enumerate(videos, 1):
                if self.stop_event.is_set():
                    break
                if idx > 1 and self.stop_after_clip is not None and self.stop_after_clip.is_set():
                    logger.info("Stopped after the clip, as asked; the rest are left for the next run.")
                    self._halted = True
                    break
                self._batch_prefix = f"[{idx}/{total}] {os.path.basename(video)}"
                from core.common.cli_utils import print_job_header
                print_job_header(idx, total, video)
                completed = False
                try:
                    run_inpaint(
                        self.engine, video, output_dir, prompt=prompt,
                        is_dual_input=is_dual_input,
                        free_text_encoder=free_text_encoder,
                        progress_cb=self._on_progress, should_stop=self.stop_event.is_set,
                        **params,
                    )
                    succeeded += 1
                    completed = True
                except InferenceCancelled:
                    logger.warning("Cancelled during %s.", os.path.basename(video))
                    break
                except Exception as e:
                    failed += 1
                    logger.error("Failed on %s: %s", os.path.basename(video), e, exc_info=True)
                finally:
                    release_cuda_memory()
                    gc.collect()
                if completed and move_finished:
                    move_files_to_finished(
                        files_to_move=[(video, os.path.dirname(video))],
                        logger=logger, wait_before_move=0.5,
                    )
        except Exception as e:
            logger.error("Fatal error (model load?): %s", e, exc_info=True)
            fatal = f"{e.__class__.__name__}: {e}"
        finally:
            self._ui_queue.put(("done", succeeded, failed, fatal))

    # -- v1 WanInpaintingGUI._on_progress (inpainting_gui_v2.py:2526)
    def _on_progress(self, stage, current, total, message=""):
        """Thread-safe progress callback passed into the engine."""
        self._ui_queue.put(("progress", current, total, message))

    # -- v1 WanInpaintingGUI._poll_queue (inpainting_gui_v2.py:2262)
    def _poll_queue(self):
        """Drain worker->UI events on the Tk main thread, then reschedule."""
        try:
            while True:
                item = self._ui_queue.get_nowait()
                kind = item[0]
                if kind == "progress":
                    _, current, total, message = item
                    denom = total or 1
                    self.progress_var.set(max(0.0, min(100.0, 100.0 * current / denom)))
                    self.status_var.set(f"{self._batch_prefix}  {message}".strip())
                elif kind == "done":
                    self._processing_done(*item[1:])
        except queue.Empty:
            pass
        finally:
            self.after(100, self._poll_queue)

    # -- v1 WanInpaintingGUI.update_status (inpainting_gui_v2.py:2280)
    def update_status(self, message):
        self.status_var.set(message)

    # -- v1 WanInpaintingGUI._processing_done (inpainting_gui_v2.py:2534)
    def _processing_done(self, succeeded=0, failed=0, fatal=""):
        # Every path out of _run_batch lands here via the "done" queue item
        # (its finally guarantees one), so this is the one place to release.
        self._release_job()
        self._set_running_state(False)
        self._batch_prefix = ""
        elapsed_text = ""
        if self._job_started is not None:
            elapsed_text = format_duration(time.monotonic() - self._job_started)
            self._job_started = None
        took = f" in {elapsed_text}" if elapsed_text else ""
        if self.stop_event.is_set():
            self.update_status(f"Stopped after {elapsed_text or '?'}. {succeeded} done, {failed} failed.")
        elif fatal:
            self.update_status(f"Failed{took}: {fatal}")
        else:
            self.progress_var.set(100.0)
            self.update_status(f"Finished{took}. {succeeded} done, {failed} failed.")
        logger.info("Batch complete: %d succeeded, %d failed.", succeeded, failed)
        self._finish_verdict(succeeded, failed, fatal)
        if elapsed_text:
            logger.info("Total time: %s (Start to finish, including model load).", elapsed_text)

    # -- v1 WanInpaintingGUI.stop_processing (inpainting_gui_v2.py:2554)
    def stop_processing(self):
        self.stop_event.set()
        self.update_status("Stopping (finishing current step)...")

    # -- v1 WanInpaintingGUI.is_busy (inpainting_gui_v2.py:2584)
    def is_busy(self):
        """True while the batch worker is running.

        The shell gates app-close and GPU handover on this, so it has to be
        honest even mid-model-load.
        """
        thread = getattr(self, "worker_thread", None)
        return bool(thread is not None and thread.is_alive())

    # -- v1 WanInpaintingGUI.holds_gpu (inpainting_gui_v2.py:2593)
    def holds_gpu(self):
        """True once the Wan engine is loaded. 14B weights are not something a
        second stage can load alongside."""
        return getattr(self, "engine", None) is not None

    # -- v1 WanInpaintingGUI.release_gpu (inpainting_gui_v2.py:2598)
    def release_gpu(self):
        """Drop the engine and empty the cache. Idempotent, per the contract.

        Refuses while the worker is alive: the thread holds references to the
        engine, so clearing it here would not free anything and would leave the
        run using a half-dismantled object.
        """
        if self.is_busy():
            logger.warning("Wan inpainting is running; not releasing the GPU.")
            return
        if self.engine is None:
            return
        # mmgp pins its host buffers and hooks the modules; dropping our
        # reference leaves all of that allocated. release() gives it back
        # (a no-op for every other offload mode).
        try:
            self.engine.release()
        except Exception:
            logger.exception("Wan engine release failed")
        self.engine = None
        self._engine_paths = None
        try:
            release_cuda_memory()
        except Exception:
            logger.exception("release_cuda_memory failed")
        gc.collect()
        logger.info("Wan inpainting engine released.")

    # -- v1 WanInpaintingGUI.shutdown (inpainting_gui_v2.py:2626)
    def shutdown(self):
        """Shell teardown. Signals the worker and frees weights, but never
        destroys anything -- the shell owns the window."""
        try:
            self.stop_event.set()
        except Exception:
            pass
        self.release_gpu()

    # -- v1 WanInpaintingGUI.restore_finished_files (inpainting_gui_v2.py:2163)
    def restore_finished_files(self):
        """Moves all files from the 'finished' folder back to the input folder."""
        if not messagebox.askyesno(
            "Restore Finished Files",
            "Are you sure you want to move all processed videos from the 'finished' "
            "folder back to the input folder?",
        ):
            return
        input_path = self.input_folder_var.get().strip()
        input_folder = input_path if os.path.isdir(input_path) else os.path.dirname(input_path)
        if not input_folder or not os.path.isdir(input_folder):
            messagebox.showerror("Restore Finished", "Input folder does not exist.")
            return
        restored_count, errors_count, _failed = _restore_finished_files([(input_folder, "finished")], logger=logger)
        messagebox.showinfo(
            "Restore Finished",
            f"Finished files restoration attempted.\n{restored_count} files moved.\n{errors_count} errors occurred.",
        )

